CREATE OR REPLACE FUNCTION public.guard_credit_approval_task() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN IF TG_OP='INSERT' THEN IF NEW.credit_profile_id IS NOT NULL THEN RAISE EXCEPTION 'Kreditlimitfreigaben ausschließlich über die Freigabeentscheidung bearbeiten' USING ERRCODE='42501'; END IF; ELSIF TG_OP='DELETE' THEN IF OLD.credit_profile_id IS NOT NULL THEN RAISE EXCEPTION 'Kreditlimitfreigaben ausschließlich über die Freigabeentscheidung bearbeiten' USING ERRCODE='42501'; END IF; ELSIF OLD.credit_profile_id IS NOT NULL OR NEW.credit_profile_id IS NOT NULL THEN RAISE EXCEPTION 'Kreditlimitfreigaben ausschließlich über die Freigabeentscheidung bearbeiten' USING ERRCODE='42501'; END IF; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.guard_credit_approval_item() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') AND EXISTS(SELECT 1 FROM public.staff_todo_lists WHERE credit_profile_id IS NOT NULL AND id IN (CASE WHEN TG_OP<>'INSERT' THEN OLD.list_id END,CASE WHEN TG_OP<>'DELETE' THEN NEW.list_id END)) THEN RAISE EXCEPTION 'Kreditlimitfreigabe nur durch ausdrückliche Entscheidung abschließen' USING ERRCODE='42501'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_credit_approval_item BEFORE INSERT OR UPDATE OR DELETE ON public.staff_todo_items FOR EACH ROW EXECUTE FUNCTION public.guard_credit_approval_item();